mapper.select:
SELECT  FROM tianquan_oauth.oauth_interaction
WHERE tenant_id = #{tenantId} AND retain_until <= #{now}
  AND id > #{afterId} AND deleted_at IS NULL ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE tianquan_oauth.oauth_interaction
SET csrf_digest = #{po.csrfDigest}, approved_scopes = #{po.approvedScopes,typeHandler=top.egon.cola.platform.tianquan.shoubing.admin.oauth.dao.OAuthStringListJsonbTypeHandler}, authentication_jti_digest = #{po.authenticationJtiDigest}, restricted_subject = #{po.restrictedSubject}, state = #{po.state}, retain_until = #{po.retainUntil}, consumed_at = #{po.consumedAt}, failure_code = #{po.failureCode}, version = #{po.version}, update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id} AND interaction_id = #{po.interactionId}
  AND version = #{expectedVersion} AND deleted_at IS NULL
  AND (#{po.state} IN ('CANCELLED', 'EXPIRED', 'CLOSED') OR expires_at > CURRENT_TIMESTAMP)

UPDATE tianquan_oauth.oauth_interaction t
SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_time = #{now}, update_user_id = #{actor}
WHERE tenant_id = #{tenantId} AND id = #{id} AND version = #{expectedVersion}
  AND deleted_at IS NULL AND retain_until <= #{now}
  AND expires_at <= #{now}
  AND NOT EXISTS (SELECT 1 FROM tianquan_oauth.oauth_authorization a WHERE a.tenant_id = #{tenantId} AND a.interaction_id = t.interaction_id AND a.deleted_at IS NULL)
